import React from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import { useState, useEffect } from "react";
import "../styles/Search.css"; // Make sure this is the updated CSS

const GigBoard = () => {
  const [selectedFilter, setFilter] = useState("keyword");
  const [keywords, setKeywords] = useState("");
  const [gigs, setGigs] = useState([]);
  const navigate = useNavigate();

  const getGigs = async () => {
    try {
      let params = {};
      switch (selectedFilter) {
        case "keyword":
          params.keyword = keywords;
          break;
        case "username":
          params.username = keywords;
          break;
        case "genre":
          params.genre = keywords;
          break;
        case "city":
          params.city = keywords;
          break;
        default:
          break;
      }

      const token = localStorage.getItem("token");

      const response = await axios.get("http://localhost:5000/api/gigs/search", {
        headers: { Authorization: `Bearer ${token}` },
        params: params,
      });

      setGigs(response.data);
    } catch (error) {
      console.error("Error fetching gigs:", error);
      setGigs([]);
    }
  };

  const viewPosting = (gig) => {
    navigate(`/gig/${gig._id}`);
  };

  useEffect(() => {
    getGigs();
  }, []);

  return (
    <div className="search-container">
      <h2 className="profile-title">GIG BOARD</h2>
      <div className="filter-container">
        <p>Please select a search filter.</p>
        <div className="search-bar">
          <input
            type="text"
            placeholder="keywords here..."
            value={keywords}
            onChange={(e) => setKeywords(e.target.value)}
          />
          <button className="search-btn" onClick={getGigs}>
            Search
          </button>
        </div>
        <div className="filter-buttons">
          <button
            className={`filter-btn ${selectedFilter === "keyword" ? "active" : ""}`}
            onClick={() => setFilter("keyword")}
          >
            Keyword
          </button>
          <button
            className={`filter-btn ${selectedFilter === "username" ? "active" : ""}`}
            onClick={() => setFilter("username")}
          >
            Username
          </button>
          <button
            className={`filter-btn ${selectedFilter === "genre" ? "active" : ""}`}
            onClick={() => setFilter("genre")}
          >
            Genre
          </button>
          <button
            className={`filter-btn ${selectedFilter === "city" ? "active" : ""}`}
            onClick={() => setFilter("city")}
          >
            City
          </button>
        </div>
        <p>
          Searching by <b>{selectedFilter}</b>
        </p>
      </div>

      <div className="grid-container">
        {gigs.map((gig) => (
          <div key={gig._id} className="user-card">
            <h2>{gig.title}</h2>
            <div className="username">{gig.username}</div>
            <div className="info-text">{gig.gigType}</div>
            <div className="info-text">{gig.genre?.join(", ")}</div>
            <div className="info-text">{gig.city}</div>
            <div className="info-text">{gig.description}</div>
            <div className="expires">
              Expires: {gig.expiryDate?.split("T")[0]}
            </div>
            <button
              className="view-profile-button"
              onClick={() => viewPosting(gig)}
            >
              View Posting
            </button>
          </div>
        ))}
      </div>
    </div>
  );
};

export default GigBoard;
